import {normalizePatent,selectedPatents,filterPatents,costLabel,validateSynthesis} from './patents.js';
import {rank} from './core.js';
import {newProject,safeURL,financials,accessStatus,missingEvidence,context,draftPlan,exportPlan,validateProject,fingerprint} from './venture-core.js';
import {discoverProviders,runAI} from './ai-client.js';
const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='patent2market-venture-v2';let p=newProject(),settings={provider:'guided',ollamaURL:'http://localhost:11434',ollamaModel:'',consent:false};try{const stored=JSON.parse(localStorage.getItem(STORAGE)||'null');if(stored){p=validateProject(stored);if(stored.aiResults&&typeof stored.aiResults==='object')p.aiResults=stored.aiResults;}}catch{}
let step=0,catalog=[],category='',limit=8,onlyReviewed=false,fullTextOnly=true,territory='',liveEnabled=false,liveBusy=false,pendingProposal=null,aiBusy=false,controller,providerInfo={cloud:[],browser:'unavailable'},toastTimer,planInput=null;try{const stored=JSON.parse(localStorage.getItem(STORAGE)||'null');planInput=typeof stored?._planInput==='string'?stored._planInput:null;}catch{}
const labels=['The problem','Technology','Your offer','The evidence','The numbers','Your plan'];
const coach=[['Find the useful question.','Turn a broad problem into a specific customer need. Your assistant asks the questions that change the direction.','clarify','Help clarify my opportunity'],['See beyond the patent.','Understand the mechanism, what it might help with, and the technical questions to investigate.','technology','Explain my selected technology'],['Useful ingredients. Different businesses.','Explore a product, a service, or a simpler route to the same outcome. Choose the offer that fits your customer.','concepts','Explore business concepts'],['Trade guesses for evidence.','Find the conversations, comparisons, and tests that would make this business more credible.','research','Design my evidence plan'],['Give the idea a reality check.','Challenge the economics, the difficult assumptions, and whether a simpler approach could work.','critique','Challenge my assumptions'],['Make the plan useful.','Bring your decisions, evidence, and numbers into a coherent business plan with explicit next steps.','plan','Write my business plan']];
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function save(){p.updatedAt=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify({...p,_planInput:planInput}));$('#save-status').textContent='Saved on this device';}catch{$('#save-status').textContent='Storage unavailable — export your project';}summary();}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
function field(key,label,placeholder='',type='text',value=p[key]){return `<div class="field"><label for="field-${key}">${label}</label>${type==='textarea'?`<textarea id="field-${key}" data-field="${key}" rows="4" maxlength="12000" placeholder="${escape(placeholder)}">${escape(value)}</textarea>`:`<input id="field-${key}" data-field="${key}" type="${type}" maxlength="500" value="${escape(value)}" placeholder="${escape(placeholder)}">`}</div>`;}
function head(number,title,copy){return `<div class="page-head"><span class="eyebrow">${number} / ${labels[number-1].toUpperCase()}</span><h2>${title}</h2><p>${copy}</p></div>`;}
function actions(){return `<div class="section-actions">${step?'<button class="secondary" data-back>← Previous step</button>':'<span class="small muted">Start rough. You can refine everything later.</span>'}${step<5?`<button class="primary" data-next>${['Explore technologies','Shape the offer','Build the evidence','Explore the numbers','Build my plan'][step]} →</button>`:''}</div>`;}
function summary(){const completed=[!!p.problem,!!p.technology,!!p.offer,!!p.evidence.length,false,!!p.sections.length];$('#steps').innerHTML=labels.map((label,i)=>`<button class="step ${i===step?'active':''} ${completed[i]?'done':''}" data-step="${i}" ${i===step?'aria-current="step"':''}><span class="step-num">${completed[i]?'✓':i+1}</span>${label}</button>`).join('');$('#project-summary').innerHTML=`<div class="summary-row"><strong>PROJECT</strong>${escape(p.name)}</div><div class="summary-row"><strong>WHO YOU WANT TO HELP</strong>${escape(p.customer||'Still taking shape')}</div><div class="summary-row"><strong>TECHNOLOGY LEAD</strong>${escape(selectedPatents(p).map(t=>t.title).join(' + ')||'Not chosen yet')}</div><div class="summary-row"><strong>EVIDENCE</strong>${p.evidence.length} source${p.evidence.length===1?'':'s'} recorded · ${missingEvidence(p).length} gaps to explore</div><div class="summary-row"><strong>BUSINESS PLAN</strong>${p.sections.length?'Draft created · review and refine':'Not drafted yet'}</div>`;}
function render(){summary();const c=coach[step];$('#coach-title').textContent=c[0];$('#coach-copy').textContent=c[1];$('#coach-action').textContent='✧ '+c[3];$('#coach-action').disabled=aiBusy;$('#coach-output').innerHTML=aiHTML(p.aiResults[c[2]]?.result);const views=[problemView,technologyView,offerView,evidenceView,numbersView,planView];$('#content').innerHTML=views[step]()+actions();if(step===1)renderTechnologies();if(step===4)updateNumbers();}
function problemView(){return head(1,'What needs to change?','Tell us about a problem you have noticed. Everyday language is enough; begin with the people affected and what is difficult for them.')+`<div class="panel">${field('problem','Describe the problem or opportunity','Who is struggling, with what, and why does it matter?','textarea')}<div class="example-row"><button data-example="water">Safer community water</button><button data-example="food">Less food spoilage</button><button data-example="cooling">Affordable cooling</button></div></div><div class="panel"><h3>Give the idea a little context</h3><p>You do not need all the answers yet.</p><div class="form-grid">${field('customer','Who would use or pay for a solution?','e.g. Small food distributors')}${field('geography','Where would you start?','e.g. One city or region')}${field('name','Working venture name','A name you can change later')}${field('advantage','What can you bring?','Experience, relationships, skills or resources')}<div class="wide">${field('constraints','What must a solution respect?','Budget, power, maintenance, accessibility, safety…','textarea')}</div></div></div>`;}
function availablePatents(){return [...new Map([...catalog,...selectedPatents(p)].map(t=>[t.id,t])).values()];}
function matchingPatents(query=p.query||p.problem){return rank(filterPatents(availablePatents(),{fullText:fullTextOnly,openOnly:onlyReviewed,jurisdiction:territory,category}),query);}
function technologyView(){return head(2,'Build a solution from existing knowledge.','Look across countries. Choose one invention, combine complementary approaches, or ask AI to propose a direction for you.')+`<div class="notice">Readable patent text and permission to use an invention are separate. Reported expiry applies to a document and territory; check the official register and related patent family before relying on it.</div><div class="panel"><h3>Your technology ingredients · ${selectedPatents(p).length}/6</h3>${selectedPatents(p).map((t,i)=>`<div class="evidence-item"><strong>[T${i+1}] ${escape(t.title)}</strong><p>${escape(t.jurisdiction||'Territory unknown')} · ${escape(t.basisOrigin||'user-recorded')} · ${escape(t.statusLabel||t.access||'access unknown')}</p><p class="small">${escape(costLabel(t))}</p><button class="secondary" data-access="${i}">Review text, rights & costs</button><button class="quiet" data-remove-tech="${i}">Remove</button></div>`).join('')||'<p>No ingredients selected yet. AI can suggest a combination from the matching documents.</p>'}<button class="primary" data-autopilot ${aiBusy?'disabled':''}>✧ Propose a solution for me</button><p class="small muted">Semi-autopilot: clarify → search with your filters → propose → your review. Uses the available collection; live worldwide search runs only when configured. Nothing is selected until you accept.</p></div><div class="search-row"><input id="tech-search" aria-label="Technology search" maxlength="600" value="${escape(p.query||p.problem)}" placeholder="Technical function, problem, or invention"><button class="primary" id="search-tech">Search collection</button></div><div class="filters"><label><input id="fulltext-only" type="checkbox" ${fullTextOnly?'checked':''}> Full document available to read</label><label><input id="reviewed-only" type="checkbox" ${onlyReviewed?'checked':''}> Only documented expired / open-license leads</label><select id="tech-territory" aria-label="Patent jurisdiction"><option value="">All jurisdictions</option>${[...new Set(availablePatents().map(t=>t.jurisdiction).filter(Boolean))].sort().map(c=>`<option ${territory===c?'selected':''}>${escape(c)}</option>`).join('')}</select></div><p class="small muted">The access filter excludes unknown and restricted rights. Private ownership alone does not determine whether an invention can be used. Source-reported status and user assessments still need verification.</p><div class="inline-actions"><button class="secondary" id="live-search" ${!liveEnabled||liveBusy?'disabled':''}>${liveBusy?'Searching…':'Search worldwide via Lens'}</button><button class="secondary" data-import-tech>Add any patent or open design</button></div><p class="small muted">${liveEnabled?'Live search: first 30 Lens matches; coverage varies. Search terms are sent to Lens.':'Live worldwide API not connected. The host needs an approved Lens API credential. External search and import remain available.'} Local collection: two international reference records plus 402 NASA summaries and your selected imports. Full-document filtering hides summary-only records.</p><p><a href="https://patents.google.com/?q=${encodeURIComponent(p.query||p.problem)}" target="_blank" rel="noopener noreferrer">Search Google Patents worldwide ↗</a> · <a href="https://worldwide.espacenet.com/" target="_blank" rel="noopener noreferrer">Espacenet ↗</a> · <a href="https://patentscope.wipo.int/" target="_blank" rel="noopener noreferrer">WIPO PATENTSCOPE ↗</a></p><p class="small muted" id="tech-count"></p><div id="tech-results"></div><button class="secondary" id="tech-more">Show more</button>`;}
function renderTechnologies(){const results=matchingPatents();$('#tech-count').textContent=`${results.length} matching leads in the available collection · relevance is not technical fit`;$('#tech-results').innerHTML=results.slice(0,limit).map(({record:t})=>`<article class="technology"><span class="badge">${escape(t.jurisdiction||'US')} · ${escape(t.category)}</span><h3>${escape(t.title)}</h3><p>${escape(t.description)}</p><p class="small">${t.fullTextAvailable?'Full document linked':'Complete text not confirmed'} · ${escape(t.statusLabel||t.access||'Rights unknown')}</p><p class="small">${escape(costLabel(t))}</p>${t.costURL?`<a href="${escape(t.costURL)}" target="_blank" rel="noopener noreferrer">Published cost source ↗</a>`:''}<div class="technology-actions"><a href="${escape(safeURL(t.fullTextURL||t.url))}" target="_blank" rel="noopener noreferrer">Read source document ↗</a><button class="secondary" data-select-tech="${escape(t.id)}" ${selectedPatents(p).some(x=>x.id===t.id)?'disabled':''}>${selectedPatents(p).some(x=>x.id===t.id)?'Added ✓':'+ Add ingredient'}</button></div></article>`).join('')||'<div class="empty">No documents match these filters in this collection. Search worldwide using the links above and import a document, or change the filters. AI will not invent a missing patent.</div>';$('#tech-more').hidden=results.length<=limit;}
async function searchWorldwide(query,signal){const response=await fetch('./api/patents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:query.slice(0,600)}),signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Worldwide search failed');catalog=[...new Map([...catalog,...data.records.map(normalizePatent).filter(Boolean)].map(t=>[t.id,t])).values()];return data;}
async function autopilot(){if(aiBusy)return;if(!p.problem.trim()){notify('Describe your problem first.');go(0);return;}if(settings.provider==='guided'||!settings.consent){await aiSettings();return;}aiBusy=true;controller=new AbortController();const started=fingerprint(p),filters=JSON.stringify([fullTextOnly,onlyReviewed,territory,category]),timer=setTimeout(()=>controller.abort(),360000);pendingProposal=null;render();$('#cancel-ai').hidden=false;try{$('#ai-status').textContent='1/3 · Clarifying the technical functions…';const clarification=await runAI('clarify',context(p),settings,controller.signal);const query=clarification.result.searchTerms||p.problem;$('#ai-status').textContent='2/3 · Finding documents under your filters…';if(liveEnabled)await searchWorldwide(query,controller.signal);const candidates=matchingPatents(query).slice(0,8).map(x=>x.record);$('#ai-status').textContent='3/3 · Designing a proposal and its first test…';const response=await runAI('synthesis',{...context(p),candidates,searchScope:liveEnabled?'First 30 live results plus local collection':'Small local reference collection and imported documents; not a worldwide search',filters:{fullTextOnly,onlyReviewed,territory}},settings,controller.signal);if(controller.signal.aborted)throw Error('Cancelled');if(fingerprint(p)!==started||JSON.stringify([fullTextOnly,onlyReviewed,territory,category])!==filters)throw Error('Inputs or filters changed. Run the proposal again for your latest choices.');validateSynthesis(response.result,candidates);pendingProposal={response,candidates,started,filters};showProposal();$('#ai-status').textContent='Proposal ready. Review the evidence and integration risks before accepting.';}catch(error){$('#ai-status').textContent=controller.signal.aborted?'Proposal cancelled or timed out. Your selections are unchanged.':error.message;}finally{clearTimeout(timer);aiBusy=false;$('#cancel-ai').hidden=true;render();}}
function showProposal(){const proposal=pendingProposal;if(!proposal)return;const r=proposal.response.result;modal(`<h2>A proposed solution</h2><span class="badge">AI HYPOTHESIS · YOUR REVIEW</span><p>${escape(r.solution)}</p>${r.components.map(c=>`<h3>${escape(proposal.candidates.find(t=>t.id===c.patentId).title)}</h3><p>${escape(c.role)}</p><blockquote>${escape(c.evidenceQuote)}</blockquote><p><strong>Integration risk:</strong> ${escape(c.integrationRisk)}</p>`).join('')||'<p>This proposal uses no patent from the available candidates.</p>'}<h3>Other ingredients needed</h3><ul>${r.additionalInputs.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><h3>First experiment</h3><p>${escape(r.firstExperiment)}</p><h3>Simpler alternative</h3><p>${escape(r.simplerAlternative)}</p><h3>Your next decisions</h3><ul>${r.nextQuestions.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><p class="small">Accepting replaces your selected technologies and solution concept. Your evidence and financial inputs remain yours to complete.</p><button class="primary" id="accept-proposal">Use this direction</button>`);$('#accept-proposal').onclick=()=>{if(fingerprint(p)!==proposal.started||JSON.stringify([fullTextOnly,onlyReviewed,territory,category])!==proposal.filters){notify('The project changed. Generate a fresh proposal.');$('#modal').close();return;}p.technologies=r.components.map(c=>({...proposal.candidates.find(t=>t.id===c.patentId)}));p.technology=p.technologies[0]||null;p.concept=r.solution+'\n\n'+r.components.map(c=>c.patentId+': '+c.role+'; integration risk: '+c.integrationRisk).join('\n')+'\nAdditional inputs: '+r.additionalInputs.join('; ')+'\nFirst experiment: '+r.firstExperiment+'\nSimpler alternative: '+r.simplerAlternative+'\nQuestions: '+r.nextQuestions.join('; ');p.aiResults.synthesis=proposal.response;pendingProposal=null;save();$('#modal').close();go(2);};}
function offerView(){const concepts=p.aiResults.concepts?.result?.concepts;return head(3,'Turn an invention into an offer.','A patent is one ingredient. The business also needs a useful service, a delivery model, and a clear reason for customers to choose it.')+`${!p.technology?'<div class="notice">You can explore a business without a patent. Describe the technical approach and evidence it needs.</div>':''}${concepts?`<div class="concepts">${concepts.map((c,i)=>`<article class="panel concept"><span class="badge">AI HYPOTHESIS ${i+1}</span><h3 style="margin-top:12px">${escape(c.name)}</h3><p>${escape(c.offer)}</p><div class="label">HOW IT COULD WORK</div><p>${escape(c.mechanism)}</p><div class="label">REVENUE MODEL</div><p>${escape(c.revenue)}</p><div class="label">FIRST TEST</div><p>${escape(c.firstTest)}</p><div class="label">CRITICAL ASSUMPTION</div><p>${escape(c.risk)}</p><button class="secondary" data-use-concept="${i}">Use this direction</button></article>`).join('')}</div>`:'<div class="notice">Ask your thinking partner for three different business concepts, or describe your own below.</div>'}<div class="panel">${field('concept','How could the solution work?','Combine the technology with the service, components, or expertise it would need.','textarea')}${field('offer','What exactly would a customer buy?','A device, a managed service, a subscription, a kit…','textarea')}${field('channel','How would you reach the first customers?','A local partner, direct outreach, an existing distributor…','textarea')}</div>`;}
function evidenceView(){return head(4,'What would make this believable?','Bring in customer conversations, technical findings, supplier quotes, and competitor information. Your plan will distinguish these inputs from untested ideas.')+`<div class="panel"><h3>The next evidence to collect</h3><ul class="checklist">${missingEvidence(p).map(g=>`<li>${escape(g)}</li>`).join('')||'<li>Review the quality, date, and independence of your evidence.</li>'}</ul><button class="secondary" data-add-evidence>+ Add evidence or an observation</button></div><div class="panel"><h3>Your evidence notebook</h3>${p.evidence.map((e,i)=>`<article class="evidence-item"><span class="badge">E${i+1} · ${escape(e.kind)}</span><h4 style="margin-top:10px">${escape(e.title)}</h4><p>${escape(e.note)}</p>${safeURL(e.url)?`<a href="${escape(safeURL(e.url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:'<span class="small muted">User-provided observation</span>'}<span class="small muted"> · ${escape(e.date||'Undated')}</span><button class="quiet" data-remove-evidence="${i}">Remove</button></article>`).join('')||'<p>No evidence recorded yet. A short, specific observation is more useful than a confident guess.</p>'}</div><div class="panel">${field('notes','What else should the plan take into account?','Interview findings, operating context, distribution partners, or unanswered questions. Avoid personal or confidential details you do not need.','textarea')}</div>`;}
function numbersView(){const fields=[['price','Price per unit of sale'],['unitCost','Variable cost per unit'],['monthlyUnits','Units sold in month one'],['growth','Monthly volume growth (%)'],['fixedCost','Monthly fixed costs'],['startupCost','Upfront launch cost'],['capital','Available starting capital']];return head(5,'Make the numbers tell a story.','Start with a simple unit of sale: a device, a service visit, or a monthly subscription. Change the assumptions and see what the business would require.')+`<div class="notice warning">Starting values are illustrative, not market estimates. Replace them with quotes and customer evidence. All scenarios assume immediate payment and constant price and costs.</div><div class="panel"><div class="form-grid"><div class="field"><label for="currency">Currency</label><select id="currency">${['USD','EUR','GBP','INR','CAD','AUD','KES','NGN','ZAR','BRL'].map(c=>`<option ${p.financial.currency===c?'selected':''}>${c}</option>`).join('')}</select></div>${fields.map(([k,l])=>`<div class="field"><label for="number-${k}">${l}</label><input id="number-${k}" type="number" min="0" max="${k==='growth'?100:1000000000}" step="${['monthlyUnits'].includes(k)?'1':'0.01'}" data-number="${k}" value="${p.financial[k]}"></div>`).join('')}</div><div id="financial-output"></div></div><p class="small muted">Excludes taxes, financing, depreciation, inventory timing, capacity constraints, and refunds. Volume scenarios are sensitivity checks, not probabilities or forecasts.</p>`;}
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:p.financial.currency,maximumFractionDigits:0}).format(n);}
function updateNumbers(){const f=financials(p.financial);$('#financial-output').innerHTML=`<div class="metrics"><div class="metric"><span>Base year revenue</span><strong>${money(f.revenue)}</strong></div><div class="metric"><span>Monthly operating break-even</span><strong>${f.breakEven===null?'Not achievable':f.breakEven+' units'}</strong></div><div class="metric"><span>Additional funding needed</span><strong>${money(f.fundingGap)}</strong></div></div>${f.margin===null||f.margin<=0?'<div class="notice warning">Your price does not create a positive contribution per unit. More sales will not cover fixed costs at these assumptions.</div>':''}<div class="table-wrap"><table><thead><tr><th>12-month scenario</th><th>Revenue</th><th>Operating result</th><th>Ending cash</th></tr></thead><tbody>${[['Downside · 60% volume',.6],['Base · entered volume',1],['Upside · 140% volume',1.4]].map(([label,factor])=>{const s=financials(p.financial,factor);return `<tr><td>${label}</td><td>${money(s.revenue)}</td><td class="${s.profit<0?'negative':''}">${money(s.profit)}</td><td class="${s.endingCash<0?'negative':''}">${money(s.endingCash)}</td></tr>`;}).join('')}</tbody></table></div><details style="margin-top:18px"><summary class="small">Show base monthly cash flow</summary><div class="table-wrap"><table><thead><tr><th>Month</th><th>Units</th><th>Revenue</th><th>Operating result</th><th>Cash balance</th></tr></thead><tbody>${f.months.map(m=>`<tr><td>${m.month}</td><td>${m.units}</td><td>${money(m.revenue)}</td><td>${money(m.profit)}</td><td>${money(m.cash)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function planView(){
 const stale=p.sections.length&&planInput!==fingerprint(p);
 const sections=p.sections.map((s,i)=>`<details class="plan-section" open><summary>${escape(s.title)}</summary><div class="plan-text">${escape(s.text)}</div><span class="small muted">${escape(s.origin)}</span><button class="quiet" data-edit-section="${i}">Edit section</button></details>`).join('');
 return head(6,'A plan you can put to work.','Bring the opportunity, technology, offer, evidence, and finances together. Review the draft, improve the weak assumptions, and decide what to test first.')+`
 ${stale?'<div class="notice warning">Project inputs have changed. Review or regenerate the plan to align the narrative and figures.</div>':''}
 <div class="panel"><h3>${p.sections.length?'Your working business plan':'Ready to bring it together?'}</h3><p>${p.sections.length?'Every section is editable. AI-generated content remains a proposal until you verify it.':'AI can write a tailored plan from your inputs. Without a model, create a guided draft with the same structure and your calculated financials.'}</p>
 <div class="plan-toolbar"><button class="primary" data-ai-plan>✧ Write with AI</button><button class="secondary" data-guided-plan>${p.sections.length?'Rebuild guided draft':'Create guided draft'}</button>${p.sections.length?'<button class="secondary" data-export-plan>Download plan ↓</button><button class="secondary" data-print>Print / save PDF</button>':''}</div>
 ${p.sections.length?'<h1 class="print-only">'+escape(p.name)+'</h1>'+sections:'<div class="empty">Your plan will cover the customer, solution, technology access, market, business model, operations, finances, risks, and a 90-day roadmap.</div>'}</div>`;
}
function aiHTML(result){if(!result)return '';const renderValue=(v)=>{if(v===null||v===undefined)return '';if(Array.isArray(v))return '<ul>'+v.map(x=>'<li>'+renderValue(x)+'</li>').join('')+'</ul>';if(typeof v==='object')return Object.entries(v).filter(([k])=>!['sections','concepts'].includes(k)).map(([k,x])=>`<h4>${escape(k.replace(/([A-Z])/g,' $1'))}</h4>${renderValue(x)}`).join('');return '<p>'+escape(v)+'</p>';};return `<div class="ai-result"><span class="badge">AI SUGGESTION · VERIFY</span>${result.concepts?'<p>Three concepts are available in Your offer.</p>':result.sections?'<p>Your plan is ready for review.</p>':renderValue(result)}${result.searchTerms?'<button class="secondary" data-use-search>Use suggested search</button>':''}</div>`;}
async function ask(stage){if(aiBusy)return;if(!p.problem.trim()){notify('Describe the problem first so the assistant has a starting point.');go(0);return;}if(stage==='technology'&&!p.technology){notify('Choose a technology first.');return;}if(settings.provider==='guided'||!settings.consent){await aiSettings();return;}if(stage==='plan'&&p.sections.length){modal('<h2>Replace the current plan?</h2><p>Your edited sections will be replaced only if a complete new plan is returned. Download the current plan first if you want to keep a copy.</p><button class="primary" id="confirm-ai-plan">Generate replacement</button>');$('#confirm-ai-plan').onclick=()=>{$('#modal').close();executeAI(stage);};return;}await executeAI(stage);}
async function executeAI(stage){aiBusy=true;controller=new AbortController();const started=fingerprint(p),timeout=setTimeout(()=>controller.abort(),stage==='plan'?360000:180000);$('#coach-action').disabled=true;$('#cancel-ai').hidden=false;$('#ai-status').textContent='Thinking through your project… This can take a minute.';try{const result=await runAI(stage,context(p),settings,controller.signal);if(fingerprint(p)!==started)throw Error('Your project changed while the assistant was working. Run this task again to use the latest inputs.');p.aiResults[stage]=result;if(stage==='plan'){p.sections=result.result.sections.map(s=>s.title==='Financial scenarios'?{...draftPlan(p).find(x=>x.title==='Financial scenarios'),origin:'Calculated from your inputs · assumptions require validation'}:{...s,origin:`AI draft · ${result.provider} / ${result.model} · verify`});planInput=fingerprint(p);step=5;}if(stage==='concepts')step=2;save();render();$('#ai-status').textContent=`Completed with ${result.provider} · ${result.model}. Review the suggestions before using them.`;}catch(error){$('#ai-status').textContent=controller.signal.aborted?'Request cancelled or timed out. Your project is unchanged.':error.message;}finally{clearTimeout(timeout);aiBusy=false;$('#coach-action').disabled=false;$('#cancel-ai').hidden=true;}}
async function aiSettings(){modal('<h2>Choose your thinking partner</h2><p>Checking available connections…</p>');providerInfo=await discoverProviders();if(!$('#modal').open)return;$('#modal-body').innerHTML=`<h2>Choose your thinking partner</h2><p>Use a model on your device, or a cloud service configured by the site owner. API keys are never stored in this browser.</p><div class="field"><label for="provider">AI connection</label><select id="provider"><option value="guided">Guided mode — no AI</option><option value="browser" ${providerInfo.browser==='unavailable'?'disabled':''}>Browser AI — ${escape(providerInfo.browser)}</option><option value="ollama">Ollama — a model on your computer</option>${providerInfo.cloud.map(c=>`<option value="${c.id}" ${c.enabled?'':'disabled'}>${escape(c.label)} — ${c.enabled?escape(c.model):'not configured'}</option>`).join('')}</select></div><div id="ollama-fields"><div class="field"><label for="ollama-url">Local Ollama address</label><input id="ollama-url" value="${escape(settings.ollamaURL)}"></div><div class="field"><label for="ollama-model">Installed model name</label><input id="ollama-model" value="${escape(settings.ollamaModel)}" placeholder="The exact name shown in Ollama"></div><p class="small">Ollama must already be installed and running. Its allowed origins must include <code>${escape(location.origin)}</code>. Your browser may request local-network permission. Local model licenses vary.</p></div><div class="notice">Browser AI depends on browser version, hardware, and model availability. A model download may be needed. OpenAI and Gemini are optional proprietary services, not bundled open-source models.</div><label style="line-height:1.8"><input id="ai-consent" type="checkbox" ${settings.consent?'checked':''}>When I click an AI action, use my project inputs, selected technology, evidence notes, and financial assumptions with this model.</label><button class="primary" id="save-ai">Use this connection</button><details style="margin-top:20px"><summary class="small">For the site owner: cloud setup</summary><p>Configure server environment variables for one provider: <code>OPENAI_API_KEY + OPENAI_MODEL</code>, <code>GEMINI_API_KEY + GEMINI_MODEL</code>, or <code>COMPATIBLE_BASE_URL + COMPATIBLE_MODEL</code> with optional <code>COMPATIBLE_API_KEY</code>. Cloud inference may incur provider charges. See the repository setup guide. Do not paste keys into notes or source code.</p></details>`;$('#provider').value=settings.provider;function show(){ $('#ollama-fields').hidden=$('#provider').value!=='ollama';}$('#provider').onchange=show;show();$('#save-ai').onclick=()=>{const provider=$('#provider').value;if(provider!=='guided'&&!$('#ai-consent').checked){notify('Review and select the project-sharing option to enable AI.');return;}settings={provider,ollamaURL:$('#ollama-url').value,ollamaModel:$('#ollama-model').value,consent:$('#ai-consent').checked};$('#ai-label').textContent=provider==='guided'?'Connect AI':provider==='compatible'?'Connected model':provider==='browser'?'Browser AI':provider==='ollama'?'Ollama':provider==='gemini'?'Gemini':'OpenAI';$('#modal').close();notify(provider==='guided'?'Guided mode selected':'Connection selected. Click an assistant action to begin.');};}
function go(index){step=Math.max(0,Math.min(5,index));render();$('#content').focus({preventScroll:true});}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Download prepared');}
function addEvidence(){modal(`<h2>Add a useful piece of evidence</h2><p>Record what the source actually establishes. Avoid copying personal information from interviews.</p><form id="evidence-form"><div class="field"><label for="e-title">Short title</label><input id="e-title" required maxlength="500" placeholder="e.g. Interview with a local distributor"></div><div class="form-grid"><div class="field"><label for="e-kind">Evidence type</label><select id="e-kind"><option value="customer">Customer conversation</option><option value="competition">Competitor / alternative</option><option value="cost">Supplier quote / cost</option><option value="technical">Technical evidence</option><option value="market">Market data</option><option value="other">Other</option></select></div><div class="field"><label for="e-date">Date</label><input type="date" id="e-date"></div></div><div class="field"><label for="e-url">Source URL (optional)</label><input type="url" id="e-url" placeholder="https://…"></div><div class="field"><label for="e-note">What did you learn? What does it not establish?</label><textarea id="e-note" required maxlength="10000" rows="4"></textarea></div><button class="primary" type="submit">Save evidence</button></form>`);$('#evidence-form').onsubmit=e=>{e.preventDefault();if(p.evidence.length>=40){notify('Export your project before adding more than 40 evidence records.');return;}const url=$('#e-url').value;if(url&&!safeURL(url)){notify('Use an HTTP or HTTPS source URL.');return;}p.evidence.push({title:$('#e-title').value,kind:$('#e-kind').value,date:$('#e-date').value,url:safeURL(url),note:$('#e-note').value});save();$('#modal').close();render();};}
function accessModal(index=0){const t=selectedPatents(p)[index];modal(`<h2>Record the basis for using this technology</h2><p>Public patent text is not permission to use the invention. Record evidence for the applicable jurisdiction and date. This record is your assessment, not independent verification.</p><form id="access-form"><div class="field"><label for="access-kind">Access basis</label><select id="access-kind"><option value="unknown">Not established / may need a license</option><option value="open-license">An applicable open license</option><option value="expired">Relevant patent rights appear expired</option></select></div><div class="field"><label for="access-url">Authoritative source URL</label><input type="url" id="access-url" value="${escape(t.accessURL||'')}"></div><div class="form-grid"><div class="field"><label for="jurisdiction">Country / jurisdiction</label><input id="jurisdiction" value="${escape(t.jurisdiction||'')}"></div><div class="field"><label for="checked-at">Date checked</label><input id="checked-at" type="date" value="${escape(t.checkedAt||'')}"></div></div><div class="field"><label for="access-evidence">Evidence, applicable conditions, and remaining uncertainty</label><textarea id="access-evidence" rows="4" maxlength="12000">${escape(t.accessEvidence||'')}</textarea></div><div class="field"><label for="full-text-url">Full document URL (description and claims)</label><input id="full-text-url" type="url" value="${escape(t.fullTextURL||'')}"></div><div class="field"><label for="full-text-evidence">What complete text did you review? Leave blank if unconfirmed.</label><textarea id="full-text-evidence">${escape(t.fullTextEvidence||'')}</textarea></div><div class="field"><label for="claims-excerpt">Relevant claims / technical excerpts for AI (optional; up to 6,000 characters)</label><textarea id="claims-excerpt" maxlength="6000">${escape(t.claimsExcerpt||'')}</textarea></div><div class="field"><label for="cost-terms">Published usage price and terms (currency, upfront fees, royalties, eligibility)</label><textarea id="cost-terms">${escape(t.costTerms||'')}</textarea></div><div class="field"><label for="cost-url">Published price source URL</label><input id="cost-url" type="url" value="${escape(t.costURL||'')}"></div><div class="field"><label for="cost-date">Price checked on</label><input id="cost-date" type="date" value="${escape(t.costCheckedAt||'')}"></div><p class="small">Unknown price is not zero. Enter applicable fees into launch or operating costs after confirming terms.</p><button class="primary">Save access assessment</button></form>`);$('#access-kind').value=t.access||'unknown';$('#access-form').onsubmit=e=>{e.preventDefault();const access=$('#access-kind').value,url=safeURL($('#access-url').value),note=$('#access-evidence').value,region=$('#jurisdiction').value,date=$('#checked-at').value;if(access!=='unknown'&&(!url||!note.trim()||!region.trim()||!date)){notify('Add the source, jurisdiction, date, and reasoning for this access basis.');return;}const costTerms=$('#cost-terms').value,costURL=safeURL($('#cost-url').value),costCheckedAt=$('#cost-date').value;if(costTerms&&(!costURL||!costCheckedAt)){notify('Published prices need a source URL and checked date.');return;}const fullTextURL=safeURL($('#full-text-url').value),fullTextEvidence=$('#full-text-evidence').value;Object.assign(t,{access,accessURL:url,accessEvidence:note,jurisdiction:region,checkedAt:date,basisOrigin:'user-recorded',statusLabel:access,fullTextURL,fullTextEvidence,fullTextAvailable:!!fullTextURL&&!!fullTextEvidence.trim(),claimsExcerpt:$('#claims-excerpt').value,costTerms,costURL,costCheckedAt});save();$('#modal').close();render();};}
function importTechnology(){modal(`<h2>Bring your own technology lead</h2><p>Add a patent, open design, or other technical source. Describe the mechanism without assuming that access or performance has been established.</p><form id="tech-form"><div class="field"><label for="t-title">Technology title</label><input id="t-title" required maxlength="500"></div><div class="field"><label for="t-id">Patent or source identifier (optional)</label><input id="t-id" maxlength="200"></div><div class="field"><label for="t-url">Source URL</label><input id="t-url" type="url" required></div><div class="field"><label for="t-description">What the source describes</label><textarea id="t-description" required maxlength="12000"></textarea></div><button class="primary">Use this technology lead</button></form>`);$('#tech-form').onsubmit=e=>{e.preventDefault();const url=safeURL($('#t-url').value);if(!url){notify('Use an HTTP or HTTPS source URL.');return;}if(selectedPatents(p).length>=6){notify('Remove an ingredient before adding another (maximum six).');return;}const imported={id:$('#t-id').value||'user-'+crypto.randomUUID(),title:$('#t-title').value,description:$('#t-description').value,url,category:'User-added source',retrievedAt:new Date().toISOString().slice(0,10),access:'unknown'};if(selectedPatents(p).some(t=>t.id===imported.id)){notify('That identifier is already selected. Edit its existing record.');return;}p.technologies=[...selectedPatents(p),normalizePatent(imported)];p.technology=p.technologies[0];save();accessModal(p.technologies.length-1);render();};}
function projectMenu(){modal(`<h2>Your project, your work</h2><p>Projects are stored in this browser. Download a project backup to move between devices or keep an editable copy. AI connection settings are session-only.</p><div class="inline-actions"><button class="primary" id="backup">Download project JSON</button><button class="secondary" id="restore">Import project JSON</button><button class="secondary" id="new-project">Start a new project</button></div>`);$('#backup').onclick=()=>download('patent2market-project.json',JSON.stringify(p,null,2),'application/json');$('#restore').onclick=()=>$('#import-file').click();$('#new-project').onclick=()=>{modal('<h2>Start fresh?</h2><p>Your current browser workspace will be replaced. Download a project backup first if you want to keep it.</p><button class="primary" id="confirm-new">Replace workspace with a new project</button>');$('#confirm-new').onclick=()=>{controller?.abort();p=newProject();step=0;planInput=null;save();$('#modal').close();render();};};}
$('#steps').onclick=e=>{const b=e.target.closest('[data-step]');if(b)go(Number(b.dataset.step));};
$('#content').addEventListener('input',e=>{const key=e.target.dataset.field;if(key){p[key]=e.target.value;save();}const n=e.target.dataset.number;if(n){const value=Number(e.target.value);if(Number.isFinite(value)&&value>=0&&value<=(n==='growth'?100:1e9)){e.target.setCustomValidity('');p.financial[n]=value;save();updateNumbers();}else{e.target.setCustomValidity('Enter a nonnegative value within the allowed range.');$('#financial-output').innerHTML='<div class="notice warning">Correct the invalid financial input to view scenarios. The previous valid value is still saved.</div>';}}});
$('#content').addEventListener('change',e=>{if(e.target.id==='tech-category'){category=e.target.value;limit=8;renderTechnologies();}if(e.target.id==='fulltext-only'){fullTextOnly=e.target.checked;renderTechnologies();}if(e.target.id==='tech-territory'){territory=e.target.value;renderTechnologies();}if(e.target.id==='reviewed-only'){onlyReviewed=e.target.checked;renderTechnologies();}if(e.target.id==='currency'){p.financial.currency=e.target.value;save();updateNumbers();}});
$('#content').onclick=e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if('next'in d){if(step===0&&!p.problem.trim()){notify('Add a short description of the problem to continue.');return;}go(step+1);}if('back'in d)go(step-1);if(d.example){const examples={water:['Families in rural communities need a reliable way to get safer drinking water with limited electricity and local maintenance.','Community water operators','Water access venture','water purification filtration'],food:['Small food distributors lose produce to spoilage during storage and transport without reliable refrigeration.','Small food distributors','Fresh route','thermal cooling temperature sensing'],cooling:['Small workshops need affordable cooling that is practical to maintain where power is unreliable.','Workshop owners','Cool work','thermal passive cooling']};const v=examples[d.example];p.problem=v[0];p.customer=v[1];p.name=v[2];p.query=v[3];save();render();}if(b.id==='search-tech'){p.query=$('#tech-search').value;limit=8;save();renderTechnologies();}if(b.id==='tech-more'){limit+=8;renderTechnologies();}if('autopilot'in d)autopilot();if(b.id==='live-search'){p.query=$('#tech-search').value;save();liveBusy=true;render();searchWorldwide(p.query,AbortSignal.timeout(35000)).then(()=>notify('Worldwide results added to the collection. Filters apply to every result.')).catch(err=>notify(err.message)).finally(()=>{liveBusy=false;render();});}if(d.selectTech){const t=availablePatents().find(r=>r.id===d.selectTech);if(selectedPatents(p).length>=6){notify('Use up to six ingredients. Remove one before adding another.');return;}if(t&&!selectedPatents(p).some(x=>x.id===t.id)){p.technologies=[...selectedPatents(p),{...t}];p.technology=p.technologies[0];save();render();}}if('access'in d)accessModal(Number(d.access));if(d.removeTech!==undefined){p.technologies=selectedPatents(p).filter((_,i)=>i!==Number(d.removeTech));p.technology=p.technologies[0]||null;save();render();}if('importTech'in d)importTechnology();if(d.useConcept!==undefined){const c=p.aiResults.concepts.result.concepts[Number(d.useConcept)];p.concept=c.mechanism||c.name;p.offer=c.offer;save();render();notify('Business direction added to your project.');}if('addEvidence'in d)addEvidence();if(d.removeEvidence!==undefined){p.evidence.splice(Number(d.removeEvidence),1);save();render();}if('aiPlan'in d)ask('plan');if('guidedPlan'in d){if(!p.problem.trim()){notify('Describe the problem before creating a plan.');go(0);return;}const generate=()=>{p.sections=draftPlan(p);planInput=fingerprint(p);save();render();notify('Guided planning draft created. Review every assumption.');};if(p.sections.length){modal('<h2>Rebuild the guided draft?</h2><p>This replaces your current plan and section edits with a fresh template based on the latest inputs.</p><button class="primary" id="confirm-guided">Replace with guided draft</button>');$('#confirm-guided').onclick=()=>{$('#modal').close();generate();};}else generate();}if('exportPlan'in d)download('patent2market-business-plan.md',exportPlan(p),'text/markdown');if('print'in d){document.querySelectorAll('.plan-section').forEach(x=>x.open=true);window.print();}if(d.editSection!==undefined){const i=Number(d.editSection),s=p.sections[i];modal(`<h2>${escape(s.title)}</h2><label for="section-edit">Edit this section</label><textarea id="section-edit" rows="16" maxlength="20000">${escape(s.text)}</textarea><button class="primary" id="save-section">Save section</button>`);$('#save-section').onclick=()=>{s.text=$('#section-edit').value;s.origin='User-edited · review evidence';save();$('#modal').close();render();};}};
$('#content').addEventListener('keydown',e=>{if(e.target.id==='tech-search'&&e.key==='Enter')$('#search-tech').click();});
$('#coach-action').onclick=()=>ask(coach[step][2]);$('#cancel-ai').onclick=()=>controller?.abort();$('#ai-settings').onclick=aiSettings;$('#close-modal').onclick=()=>$('#modal').close();$('#project-menu').onclick=projectMenu;
$('#coach-output').onclick=e=>{if(e.target.closest('[data-use-search]')){p.query=String(p.aiResults.clarify.result.searchTerms);save();go(1);}};
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000){notify('Project file is too large (maximum 2 MB).');return;}try{const imported=validateProject(JSON.parse(await file.text()));modal(`<h2>Import ${escape(imported.name)}?</h2><p>This replaces the current workspace. Download your current project first if you need to retain it.</p><button class="primary" id="confirm-import">Replace workspace with imported project</button>`);$('#confirm-import').onclick=()=>{controller?.abort();p=imported;step=0;planInput=null;save();$('#modal').close();render();notify('Project imported');};}catch(error){notify(error.message||'Could not read this project.');}};
$('#method').onclick=()=>modal('<h2>A thoughtful business starts with evidence.</h2><p>Patent2Market combines an international reference collection, optional worldwide Lens search, and NASA technology summaries, a guided venture workflow, explicit financial calculations, and optional AI assistance. Technology relevance is lexical search, not proof of suitability.</p><h3>Sources and rights</h3><p>NASA descriptions are attributed to their source. NASA does not endorse this app. The snapshot does not establish current patent status, licensing terms, or freedom to operate. User-recorded access assessments must be verified for the product and jurisdiction.</p><h3>AI and evidence</h3><p>AI results are suggestions. Worldwide patent search requires an approved Lens API credential. General market web research is not automated; its evidence assistant proposes research questions and tests. Add actual sources and observations to the notebook. Generated market or technical claims need independent verification.</p><h3>Privacy</h3><p>Project information is saved in browser storage, which is not encrypted or backed up. When you explicitly enable and request AI, project context is sent to the selected provider. Cloud providers apply their own data terms and charges. Browser AI and local Ollama run on your device where supported. No telemetry or analytics are included.</p><h3>Open foundation</h3><p>Original application code is MIT licensed with no third-party runtime packages. Optional model services are separate; OpenAI and Gemini are proprietary. Check the license of any local model you choose. The hosted preview is private; the application can be self-hosted.</p>');
render();Promise.allSettled([fetch('./catalog.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('./global-patents.json').then(r=>{if(!r.ok)throw Error();return r.json();})]).then(results=>{catalog=results.flatMap(r=>r.status==='fulfilled'?r.value.records:[]).map(normalizePatent).filter(Boolean);if(results.some(r=>r.status==='rejected'))notify('Some reference records are unavailable. You can still import a source.');if(step===1)render();});fetch('./api/patents').then(r=>r.json()).then(c=>{liveEnabled=c.enabled===true;if(step===1)render();}).catch(()=>{});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
